import { sql } from 'drizzle-orm';
import {
  type AnyPgColumn,
  boolean,
  check,
  index,
  integer,
  jsonb,
  text,
  uniqueIndex,
  uuid,
} from 'drizzle-orm/pg-core';
import {
  alertRuleConditions,
  alertRuleSeverities,
  alertSeverities,
  alertStatuses,
  branchTargetPeriodKinds,
  executiveDigestNarrativeSources,
} from '@takhti/contracts';
import { baseColumns } from '../../kernel/base-columns';
