/* The tables of M43 · Owner analytics. */

export const branchTargets = defineTable(
  'branch_targets',
  { module: 'M43', scope: 'org' },
  {
    ...baseColumns,
    branchId: uuid()
      .references((): AnyPgColumn => branches.id)
      .notNull(),
    /** a KPI from the catalogue */
    kpiKey: text().notNull(),
    periodKind: enumText(branchTargetPeriodKinds).notNull(),
    /** the first day of the period */
    periodStart: dateStr().notNull(),
    target: decimal(18, 4).notNull(),
    note: text(),
    setBy: uuid()
      .references((): AnyPgColumn => profiles.id)
      .notNull(),
  },
  (t) => [
    uniqueIndex('branch_targets_branch_kpi_key_period_kind_period_start_uq')
      .on(t.branchId, t.kpiKey, t.periodKind, t.periodStart)
      .where(live(t)),
  ],
);

export const alertRules = defineTable(
  'alert_rules',
  { module: 'M43', scope: 'org' },
  {
    ...baseColumns,
    name: text().notNull(),
    kpiKey: text().notNull(),
    condition: enumText(alertRuleConditions).notNull(),
    threshold: decimal(18, 4).notNull(),
    /** for the change conditions: this window against the one before */
    compareWindowDays: integer().notNull().default(7),
    /** empty means every branch */
    branchIds: uuid()
      .array()
      .notNull()
      .default(sql`'{}'`),
    severity: enumText(alertRuleSeverities).notNull().default('warning'),
    recipientRoleKeys: text().array().notNull(),
    /** the same rule does not fire again for the same branch within this time */
    cooldownDays: integer().notNull().default(7),
    isActive: boolean().notNull().default(true),
    /** a seeded rule that can be switched off but not deleted */
    isSystem: boolean().notNull().default(false),
  },
);

export const alerts = defineTable(
  'alerts',
  { module: 'M43', scope: 'org' },
  {
    ...baseColumns,
    ruleId: uuid()
      .references((): AnyPgColumn => alertRules.id)
      .notNull(),
    /** empty for a group-level alert */
    branchId: uuid().references((): AnyPgColumn => branches.id),
    kpiKey: text().notNull(),
    raisedOn: dateStr().notNull(),
    value: decimal(18, 4).notNull(),
    /** the target or the earlier figure */
    comparedTo: decimal(18, 4),
    severity: enumText(alertSeverities).notNull(),
    /** written from a template, in plain words */
    message: text().notNull(),
    status: enumText(alertStatuses).notNull().default('open'),
    acknowledgedBy: uuid().references((): AnyPgColumn => profiles.id),
    acknowledgedAt: timestamptz(),
    note: text(),
    /** set by the system when the condition clears, or by a person */
    resolvedOn: dateStr(),
  },
  (t) => [
    uniqueIndex('alerts_rule_branch_raised_on_uq')
      .on(
        t.ruleId,
        sql`coalesce(${t.branchId}, '00000000-0000-0000-0000-000000000000'::uuid)`,
        t.raisedOn,
      )
      .where(live(t)),
    index('alerts_status_severity_idx').on(t.orgId, t.status, t.severity),
  ],
);

/** The weekly summary as it was sent. */
export const executiveDigests = defineTable(
  'executive_digests',
  { module: 'M43', scope: 'org' },
  {
    ...baseColumns,
    weekStart: dateStr().notNull(),
    /** the figures, movements, alerts and decisions waiting */
    content: jsonb().notNull(),
    /** a short written summary */
    narrative: text(),
    narrativeSource: enumText(executiveDigestNarrativeSources).notNull().default('template'),
    sentAt: timestamptz(),
    recipientUserIds: uuid()
      .array()
      .notNull()
      .default(sql`'{}'`),
  },
  (t) => [
    check('executive_digests_week_start_monday', sql`extract(isodow from ${t.weekStart}) = 1`),
    uniqueIndex('executive_digests_week_start_uq').on(t.orgId, t.weekStart).where(live(t)),
  ],
);

/** A note the owner leaves on a branch or a figure, for themselves and the leadership. */
export const hqNotes = defineTable(
  'hq_notes',
  { module: 'M43', scope: 'org' },
  {
    ...baseColumns,
    branchId: uuid().references((): AnyPgColumn => branches.id),
    kpiKey: text(),
    noteDate: dateStr().notNull(),
    body: text().notNull(),
    authorId: uuid()
      .references((): AnyPgColumn => profiles.id)
      .notNull(),
    /** the branch's principal can read it */
    isSharedWithBranch: boolean().notNull().default(false),
  },
);
